local ModuleRegistry = (function()
local ModuleRegistry = {}

local ALLOWED_MODULES = {
    Shell = true,
}

function ModuleRegistry.new()
    local modules = {}

    return {
        register = function(name, module)
            if type(name) ~= "string" or not ALLOWED_MODULES[name] then
                return false, "Module is not allowlisted: " .. tostring(name)
            end
            if modules[name] then
                return false, "Module is already registered: " .. name
            end
            if type(module) ~= "table" or type(module.start) ~= "function" then
                return false, "Module must provide a start function: " .. name
            end

            modules[name] = module
            return true
        end,
        get = function(name)
            return modules[name]
        end,
        names = function()
            local names = {}
            for name in pairs(modules) do
                table.insert(names, name)
            end
            table.sort(names)
            return names
        end,
    }
end

return ModuleRegistry
end)()

local LoaderCore = (function()
local LoaderCore = {}

local function defaultLogger(message)
    if type(warn) == "function" then
        warn(message)
    else
        print(message)
    end
end

function LoaderCore.new(registry, logger)
    assert(type(registry) == "table", "A module registry is required")
    assert(type(registry.get) == "function", "The registry must provide get")

    local activeModules = {}
    local state = "stopped"
    local log = logger or defaultLogger

    local function reportError(operation, name, message)
        local text = ("[STAR HUB] Failed to %s module %q: %s")
            :format(operation, name, tostring(message))
        log(text)
    end

    local function updateState()
        state = next(activeModules) and "running" or "stopped"
    end

    local loader = {}

    function loader.registerModule(name, module)
        if type(registry.register) ~= "function" then
            return false, "The registry does not support registration"
        end
        return registry.register(name, module)
    end

    function loader.startModule(name, options)
        if activeModules[name] then
            return true, "already started"
        end

        local module = registry.get(name)
        if not module then
            local message = "Module is not registered"
            reportError("start", name, message)
            return false, message
        end
        if type(module.start) ~= "function" then
            local message = "Module does not provide a start function"
            reportError("start", name, message)
            return false, message
        end

        local moduleOptions = {}
        for key, value in pairs(options or {}) do
            moduleOptions[key] = value
        end

        local onClose = moduleOptions.onClose
        moduleOptions.onClose = function(...)
            activeModules[name] = nil
            updateState()
            if onClose then
                onClose(...)
            end
        end

        local ok, handle, startError = pcall(module.start, moduleOptions)
        if not ok then
            reportError("start", name, handle)
            return false, tostring(handle)
        end
        if type(handle) ~= "table" or type(handle.stop) ~= "function" then
            local message = startError or "Module start must return a handle with stop"
            reportError("start", name, message)
            return false, tostring(message)
        end

        activeModules[name] = handle
        updateState()
        return true
    end

    function loader.stopModule(name)
        local handle = activeModules[name]
        if not handle then
            return true, "not started"
        end

        activeModules[name] = nil
        updateState()
        local ok, stopError = pcall(handle.stop)
        if not ok then
            reportError("stop", name, stopError)
            return false, tostring(stopError)
        end
        return true
    end

    function loader.initialize()
        if activeModules.Shell then
            return true, "already initialized"
        end
        return loader.startModule("Shell")
    end

    function loader.stopAll()
        local names = {}
        for name in pairs(activeModules) do
            table.insert(names, name)
        end
        table.sort(names)

        local succeeded = true
        local errors = {}
        for _, name in ipairs(names) do
            local ok, message = loader.stopModule(name)
            if not ok then
                succeeded = false
                table.insert(errors, name .. ": " .. tostring(message))
            end
        end
        return succeeded, table.concat(errors, "; ")
    end

    function loader.stop()
        return loader.stopAll()
    end

    function loader.getState()
        return state
    end

    function loader.isModuleRunning(name)
        return activeModules[name] ~= nil
    end

    return loader
end

return LoaderCore
end)()

local Loader = (function()
return function(dependencies)
    assert(type(dependencies) == "table", "Loader dependencies are required")
    assert(type(dependencies.LoaderCore) == "table", "LoaderCore is required")
    assert(type(dependencies.ModuleRegistry) == "table", "ModuleRegistry is required")

    local registry = dependencies.ModuleRegistry.new()
    for name, module in pairs(dependencies.modules or {}) do
        local registered, registrationError = registry.register(name, module)
        if not registered then
            error(registrationError, 2)
        end
    end

    local loader = dependencies.LoaderCore.new(registry)
    local initialized, initializationError = loader.initialize()
    if not initialized then
        error("STAR HUB initialization failed: " .. tostring(initializationError), 2)
    end
    return loader
end
end)()

